import{_ as s,c as e,o as t,ai as i}from"./chunks/framework.B63Sb1io.js";const b=JSON.parse('{"title":"安装","titleTemplate":"GSAP 中文文档","description":"GSAP 基础","frontmatter":{"title":"安装","titleTemplate":"GSAP 中文文档","description":"GSAP 基础","layout":"doc","navbar":true,"sidebar":true,"aside":true,"outline":"deep","lastUpdated":true,"prev":false,"next":false,"tags":["GSAP","安装","动画库","JavaScript"]},"headers":[],"relativePath":"post/project/DocsTranslate/GSAP/GSAP_2.md","filePath":"post/project/DocsTranslate/GSAP/GSAP_2.md","lastUpdated":1755611679000}'),l={name:"post/project/DocsTranslate/GSAP/GSAP_2.md"};function n(p,a,r,d,o,h){return t(),e("div",null,a[0]||(a[0]=[i('<h1 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h1><p>GSAP 是“框架无关的”，这意味着它可以在 React、Webflow、Wordpress 或任何其他 JS/网页框架中使用。GSAP 核心文件和所有插件都只是 <strong>JavaScript 文件</strong>。</p><p>本文介绍了加载文件的最常见方法。具体来说，就是通过 <a href="https://www.npmjs.com/" target="_blank" rel="noreferrer">NPM</a>、<a href="https://yarnpkg.com/" target="_blank" rel="noreferrer">Yarn</a> 以及使用简单的 <code>&lt;script&gt;</code> 标签。选择你自己的方式，或者查看左侧子菜单中的安装指南，获取针对特定框架或工具的指导。</p><h2 id="获取文件" tabindex="-1">获取文件 <a class="header-anchor" href="#获取文件" aria-label="Permalink to &quot;获取文件&quot;">​</a></h2><p><a href="https://gsap.com/community/files/file/20-gsap-public-files/?do=download&amp;csrfKey=45cdfd82adb89f6e6f54634d1ae01807" target="_blank" rel="noreferrer">GSAP（点击下载）</a></p><details><summary><b>下载的压缩文件里有什么？</b></summary><hr><p>该压缩文件包含以下目录：</p><p><span class="blue-m">/minified/</span> 通过<b>脚本标签</b>加载到网页中，具有普遍兼容性，经过高度压缩以实现最快加载速度。</p><p><span class="blue-m">/UMD/</span> 压缩文件的<b>未压缩版本</b>，采用 UMD 格式。通常用于较旧的构建工具或调试。</p><p><span class="blue-m">/ESM/</span> <b>ES 模块文件</b>，经过转译以兼容现代构建工具（不包含复杂的 ES6 内容）。</p><p><span class="blue-m">/src/</span> <b>原始源代码文件</b>，这些文件是现代 ES6 模块。</p></details><h2 id="安装-1" tabindex="-1">安装 <a class="header-anchor" href="#安装-1" aria-label="Permalink to &quot;安装&quot;">​</a></h2><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-lNn1k" id="tab-CGG9d-4" checked><label data-title="npm" for="tab-CGG9d-4">npm</label><input type="radio" name="group-lNn1k" id="tab-4qo7aW_"><label data-title="CDN" for="tab-4qo7aW_">CDN</label><input type="radio" name="group-lNn1k" id="tab-K-RYLLU"><label data-title="yarn" for="tab-K-RYLLU">yarn</label></div><div class="blocks"><div class="language-sh vp-adaptive-theme active line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gsap</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">script src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://cdn.jsdelivr.net/npm/gsap@3.13.0/dist/gsap.min.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/script</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gsap</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></div></div><h3 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h3><h3 id="缓动函数" tabindex="-1">缓动函数 <a class="header-anchor" href="#缓动函数" aria-label="Permalink to &quot;缓动函数&quot;">​</a></h3>',10)]))}const u=s(l,[["render",n]]);export{b as __pageData,u as default};
